INSERT INTO `tawasulEmailTemplate` (`tawasulEmailTemplateID`, `type`, `templateType`, `moduleName`, `templateName`, `templateSubject`, `templateBody`, `variables`, `timestamp`) VALUES (NULL, 'Core', 'Staff Application Form Rejection', 'Staff', 'Staff Application Form Rejection', 'Your Application Form Status', '<p>Dear {{preferredName}},</p>\r\n<p>Thank you for your interest at {{organisationName}} and for taking the time to apply.</p>\r\n<p>After reviewing your application, we have decided to proceed with other candidates whose qualifications more closely align with our current needs. While we won\'t be moving forward at this time, we appreciate the effort you put into your application.</p>\r\n<p>We wish you the best of luck in your job search.</p>\r\n<p>This is an automated message. Please contact {{organisationEmail}} with any questions.</p>', '{\r\n\"email\": [\"safeEmail\"], \r\n\"date\": [\"date\"], \r\n\"applicationID\": [\"randomDigit\"], \r\n\"preferredName\": [\"firstName\"],\r\n\"surname\": [\"lastName\"],\r\n\"organisationEmail\": [\"safeEmail\"],\r\n\"organisationName\": [\"name\"]\r\n}', '2026-02-02 11:30:16');end
INSERT INTO `tawasulEmailTemplate` (`tawasulEmailTemplateID`, `type`, `templateType`, `moduleName`, `templateName`, `templateSubject`, `templateBody`, `variables`, `timestamp`) VALUES (NULL, 'Core', 'Staff Application Form Confirmation', 'Staff', 'Staff Application Form Confirmation', 'Staff Application Form Confirmation', '<p>Dear {{preferredName}},</p>\r\n<p>Thank you for applying for the position of {{jobTitle}} at {{organisationName}}.</p>\r\n<p>Your application was successfully submitted. Our Human Resources team will review your application and be in touch in due course.</p>\r\n<p>This is an automated message. In the meantime, should you have any questions please contact {{organisationName}} at {{organisationEmail}}. For reference, please quote the following application number(s): {{applicationID}}.</p>', '{\r\n\"email\": [\"safeEmail\"], \r\n\"date\": [\"date\"], \r\n\"applicationID\": [\"randomDigit\"], \r\n\"jobTitle\": [\"jobTitle\"], \r\n\"preferredName\": [\"firstName\"],\r\n\"surname\": [\"lastName\"],\r\n\"organisationEmail\": [\"safeEmail\"],\r\n\"organisationName\": [\"name\"]\r\n}', '2026-02-02 11:30:16');end
INSERT INTO `tawasulEmailTemplate` (`tawasulEmailTemplateID`, `type`, `templateType`, `moduleName`, `templateName`, `templateSubject`, `templateBody`, `variables`, `timestamp`) VALUES (NULL, 'Core', 'Staff Application Form Reference Request', 'Staff', 'Staff Application Form Reference Request', 'Request For Reference', '<p>To whom it may concern,</p>\r\n<p>This email is being sent in relation to the job application of an individual who has nominated you as a referee: {{preferredName}} {{surname}}.</p>\r\n<p>In assessing their application for the post of {{jobTitle}} at our school, we would like to enlist your help in completing the following reference form: {{applicationRefereeLink}}.</p>\r\n<p>Please feel free to contact me, should you have any questions in regard to this matter.</p>\r\n<p>Regards,</p>\r\n<p>{{organisationHRName}}</p>', '{\r\n\"email\": [\"safeEmail\"], \r\n\"date\": [\"date\"], \r\n\"applicationID\": [\"randomDigit\"], \r\n\"applicationRefereeLink\": \"https://tos.fiksutiliratkaisut.fi\", \r\n\"preferredName\": [\"firstName\"],\r\n\"surname\": [\"lastName\"],\r\n\"jobTitle\": [\"jobTitle\"],\r\n\"organisationHRName\": [\"name\"]\r\n}', '2026-02-02 11:30:16');end
